def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = []
    op = []
    for a, b in history:
        my.append(a)
        op.append(b)

    my_last = my[-1]
    op_last = op[-1]

    opp_d = sum(1 for x in op if x == 'D')
    opp_c = n - opp_d
    my_d = sum(1 for x in my if x == 'D')

    opp_d10 = sum(1 for x in op[-10:] if x == 'D')
    opp_c10 = min(10, n) - opp_d10

    i = n - 1
    opp_d_streak = 0
    while i >= 0 and op[i] == 'D':
        opp_d_streak += 1
        i -= 1

    i = n - 1
    opp_c_streak = 0
    while i >= 0 and op[i] == 'C':
        opp_c_streak += 1
        i -= 1

    i = n - 1
    my_d_streak = 0
    while i >= 0 and my[i] == 'D':
        my_d_streak += 1
        i -= 1

    forgive = 0
    punish = 0
    unprov = 0
    coop_after_c = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if op[i + 1] == 'C':
                forgive += 1
            else:
                punish += 1
        else:
            if op[i + 1] == 'D':
                unprov += 1
            else:
                coop_after_c += 1

    recent_punish = n >= 2 and my[n - 2] == 'D' and op[n - 1] == 'D'
    recent_forgive = n >= 2 and my[n - 2] == 'D' and op[n - 1] == 'C'

    myD_trans = forgive + punish
    myC_trans = unprov + coop_after_c

    pdD = float(punish) / float(myD_trans) if myD_trans else 0.0
    pdC = float(unprov) / float(myC_trans) if myC_trans else 0.0
    opp_d_rate = float(opp_d) / float(n)
    opp_c_rate = float(opp_c) / float(n)

    # If they are very hostile, do not keep feeding them S.
    if opp_d >= max(10, (3 * n) // 4) or opp_d10 >= 8 or opp_d_streak >= 12:
        return 'D'

    # If they defect a lot while we have mostly cooperated, defect.
    if my_d == 0 and opp_d >= 4 and opp_d * 3 >= n * 2:
        return 'D'

    # If they are strongly anti-cooperative: they defect after our C.
    if myC_trans >= 4 and pdC >= 0.62 and unprov >= 3:
        return 'D'

    # Safe probe against unconditional cooperators.  Delay past common early probes.
    if opp_d == 0:
        if my_d == 0:
            return 'D' if n >= 22 else 'C'
        if my_d == 1:
            if my_last == 'D' and op_last == 'C' and forgive == 0:
                return 'C'
            return 'D'
        return 'D'

    # Low-defection exploitable opponents: if we probed and they did not punish, exploit.
    if opp_d <= 1 and my_d >= 1 and punish == 0 and opp_c_rate >= 0.8 and pdC <= 0.5:
        if my_last == 'D' and op_last == 'C' and forgive == 0:
            return 'C'
        return 'D'

    # Later secondary probe if they have only a tiny isolated defect and are very cooperative.
    if opp_d <= 1 and my_d == 0 and n >= 50 and opp_c_rate >= 0.9:
        return 'D'

    # Strong evidence they ignore our D but defect otherwise; exploit.
    if myD_trans >= 3 and punish == 0 and forgive >= 2 and opp_c_rate >= 0.8:
        return 'D'

    if myD_trans >= 3 and pdD <= 0.35 and pdC >= 0.6 and unprov >= 3:
        return 'D'

    if op_last == 'D':
        if my_last == 'D':
            # Mutual D.  If opponent has never cooperated, try one escape to recover from
            # initial D-streak TFT-like opponents; if they are truly ALLD, resume D after one test.
            if opp_c == 0:
                if opp_d_streak <= 3:
                    return 'C'
                return 'D'

            # Direct punishment for our previous D: usually try to restore cooperation.
            if recent_punish and opp_d_streak <= 2 and (opp_c10 >= 1 or opp_c_rate > 0.3):
                return 'C'

            # If they are stubborn, keep punishing.
            if opp_d_streak >= 3 and (opp_d_rate > 0.55 or opp_d10 >= 5):
                return 'D'

            return 'C'

        # We cooperated last, opponent defected.
        # Forgive the very first unprovoked D when there has been no cooperation yet.
        if opp_d == 1 and opp_c == 0 and n <= 2:
            return 'C'

        # If this defection is mostly a response to our own earlier D, try to recover.
        if recent_punish and opp_d_streak <= 2 and (opp_c10 >= 1 or opp_c_rate > 0.3):
            return 'C'

        # Isolated mistake / one-shot aggression after cooperative run: forgive.
        if opp_d == 1 and n >= 5 and opp_c_rate > 0.7:
            return 'C'

        # Repeated unprovoked defection: retaliate.
        if opp_d_streak >= 2:
            if recent_punish and opp_c_rate > 0.6:
                return 'C'
            return 'D'

        # If they have been mostly defective recently, punish.
        if opp_d10 >= 3 and opp_c_rate < 0.7:
            return 'D'

        if opp_d >= max(3, n // 2):
            return 'D'

        # Otherwise, return to cooperation with cooperative opponents.
        if opp_c >= n - 3 and n >= 10:
            return 'C'

        return 'D'

    # Opponent cooperated last.
    if my_last == 'D':
        # We just took advantage.  Keep exploiting only if they are clearly unretaliating;
        # otherwise pause to let any delayed punishment surface.
        if n >= 90 and opp_d <= 1 and pdD <= 0.35 and pdC <= 0.35:
            return 'D'
        return 'C'

    # Mutual cooperation last round.
    if n >= 95 and opp_d <= 1 and pdD <= 0.35 and pdC <= 0.35 and my_d > 0:
        return 'D'

    return 'C'
